import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Instant Answers & Keyword Shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/instant-answers.md","filePath":"user-guide/instant-answers.md","lastUpdated":1787475408000}'),s={name:"user-guide/instant-answers.md"};function r(i,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="instant-answers-keyword-shortcuts" tabindex="-1">Instant Answers &amp; Keyword Shortcuts <a class="header-anchor" href="#instant-answers-keyword-shortcuts" aria-label="Permalink to &quot;Instant Answers &amp; Keyword Shortcuts&quot;">​</a></h1><p>Some results appear instantly as you type, without waiting for a file search — either always on, or gated behind a short keyword you type before your actual query (so a large feature like browser history search doesn&#39;t compete for attention on every unrelated keystroke). Most keyword-gated ones have their keyword configured in <strong>Settings → Plugins → Configure</strong>.</p><h2 id="always-on" tabindex="-1">Always on <a class="header-anchor" href="#always-on" aria-label="Permalink to &quot;Always on&quot;">​</a></h2><p>These need no keyword — they activate as soon as what you type matches their pattern.</p><h3 id="calculator" tabindex="-1">Calculator <a class="header-anchor" href="#calculator" aria-label="Permalink to &quot;Calculator&quot;">​</a></h3><p>Type a math expression directly and the result appears live, with <strong>Enter</strong> copying it to the clipboard:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span></code></pre></div><p>Explicit base conversion is also supported:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span></code></pre></div><h3 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h3><ul><li><code>%NAME%</code> expands a specific variable (including multi-path variables like <code>%PATH%</code>, split into one entry per path).</li><li><code>%partial</code> fuzzy-lists every variable whose name matches <code>partial</code>.</li></ul><h3 id="run-a-command" tabindex="-1">Run a command <a class="header-anchor" href="#run-a-command" aria-label="Permalink to &quot;Run a command&quot;">​</a></h3><ul><li><code>#&lt;command&gt;</code> opens a Command Prompt window and runs <code>&lt;command&gt;</code> <strong>as Administrator</strong>.</li><li><code>$&lt;command&gt;</code> opens a Command Prompt window and runs <code>&lt;command&gt;</code> normally.</li></ul><h3 id="bare-urls" tabindex="-1">Bare URLs <a class="header-anchor" href="#bare-urls" aria-label="Permalink to &quot;Bare URLs&quot;">​</a></h3><p>Type or paste a <code>http://</code>/<code>https://</code> address and Lertaro offers to open it directly.</p><h2 id="keyword-triggered-built-in-configurable-prefix" tabindex="-1">Keyword-triggered (built-in, configurable prefix) <a class="header-anchor" href="#keyword-triggered-built-in-configurable-prefix" aria-label="Permalink to &quot;Keyword-triggered (built-in, configurable prefix)&quot;">​</a></h2><p>Type the keyword, a space, then your query. Each keyword defaults to a short prefix but can be changed independently in that plugin&#39;s own <strong>Configure</strong> dialog if it collides with something you type often.</p><table tabindex="0"><thead><tr><th>Keyword (default)</th><th>Plugin</th><th>What it searches</th></tr></thead><tbody><tr><td><code>ps</code></td><td>Process Manager</td><td>Running processes by name, PID, or window title (fuzzy/pinyin matches too) — select one to kill it.</td></tr><tr><td><code>win</code></td><td>Window Switcher</td><td>Currently open, switchable windows — the same set Alt+Tab shows — by title, process name, or PID. Select one to bring it to the foreground.</td></tr><tr><td><code>bm</code></td><td>Browser Data</td><td>Bookmarks and history from Chrome/Chromium-family and Firefox-family browser profiles you&#39;ve added under that plugin&#39;s own settings.</td></tr><tr><td><code>set</code></td><td>Core Extensions</td><td>Every setting in the app, fuzzy-matched by name — pick one to jump straight to it in Settings, highlighted. Type <code>set</code> with nothing after it to list every setting.</td></tr><tr><td><code>flow</code></td><td>Flow Launcher Bridge</td><td>Lists all loaded Flow.Launcher plugins and their action keywords — select one and press Enter to open its settings window.</td></tr></tbody></table><p>Window Switcher shows a live thumbnail of each window&#39;s actual content as its icon by default, captured in the background so it never slows down typing — a plain app icon shows immediately, and the thumbnail fades in once it&#39;s ready. Turn off <strong>Show Window Content as Icon</strong> in <strong>Settings → Plugins → Window Switcher → Configure</strong> to skip that capture entirely and always use the app icon. A window running as true exclusive fullscreen (most games default to borderless windowed instead, which this handles fine) can&#39;t be captured this way and always falls back to its app icon.</p><p>Browser Data indexes bookmarks and history independently — <strong>Index Bookmarks</strong> and <strong>Index History</strong> are separate toggles in <strong>Settings → Plugins → Browser Data → Configure</strong>, so you can turn history off (it tends to grow far larger than bookmarks) while still searching bookmarks, or vice versa.</p><h2 id="web-search" tabindex="-1">Web search <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;Web search&quot;">​</a></h2><p>Web Search ships with default keywords for several engines/sites — <code>bd</code> (Baidu), <code>g</code> (Google), <code>bing</code> (Bing), <code>gh</code> (GitHub), <code>wiki</code> (Wikipedia), <code>yt</code> (YouTube) — and lets you add, edit, or remove entries entirely, each with its own name, keyword, icon, and URL template, from <strong>Settings → Plugins → Web Search → Configure</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g lertaro github</span></span></code></pre></div><p>opens a Google search for &quot;lertaro github&quot; in your browser.</p><h2 id="translation" tabindex="-1">Translation <a class="header-anchor" href="#translation" aria-label="Permalink to &quot;Translation&quot;">​</a></h2><p>Translator&#39;s default keyword is <code>tr</code>. Type text after it to translate into the language currently selected for Lertaro&#39;s interface:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tr hello</span></span></code></pre></div><p>The result appears asynchronously; press <strong>Enter</strong> or click it to copy it. The text to translate is sent to Microsoft Translator, so this feature requires an Internet connection. Its target language is the App&#39;s current language setting. Change the keyword under <strong>Settings → Plugins → Translator → Configure</strong>.</p><h2 id="file-filters" tabindex="-1">File Filters <a class="header-anchor" href="#file-filters" aria-label="Permalink to &quot;File Filters&quot;">​</a></h2><p>Index specific folders under their own rule, configured entirely under <strong>Settings → Plugins → File Filters → Configure</strong>. Each rule has its own <strong>Target Folders</strong> list (scanned recursively), an <strong>Extensions / Pattern</strong> field (e.g. <code>*.exe;*.lnk</code> — several patterns separated by <code>;</code> or <code>,</code> are all matched; the default <code>*</code> matches every file), and an optional <strong>Filter Name</strong> shown in the result description. Subfolders are always included regardless of the pattern — only files are filtered by it.</p><p>Add a <strong>Shortcut Keyword</strong> to gate a rule&#39;s matches behind a prefix, the same as the built-in keywords above, instead of always mixing them into the general index.</p><h2 id="fully-custom-you-define-the-keyword" tabindex="-1">Fully custom (you define the keyword) <a class="header-anchor" href="#fully-custom-you-define-the-keyword" aria-label="Permalink to &quot;Fully custom (you define the keyword)&quot;">​</a></h2><h3 id="custom-commands" tabindex="-1">Custom Commands <a class="header-anchor" href="#custom-commands" aria-label="Permalink to &quot;Custom Commands&quot;">​</a></h3><p>Define your own <code>&lt;keyword&gt; &lt;args&gt;</code> commands that launch an external program, configured entirely under <strong>Settings → Plugins → Custom Commands → Configure</strong>. The command&#39;s parameter template supports positional placeholders (<code>%s1</code>, <code>%s2</code>, ... for each space-separated argument) and a whole-remainder placeholder (<code>%s</code> for everything typed after the keyword).</p><p>Each command also has a <strong>Show in Quick Navigation</strong> checkbox (off by default) — turn it on to also list that command as its own entry at the root of the <a href="./hotkeys.html#quick-navigation-mouse">Quick Navigation</a> menu, clickable without typing its keyword at all. The <strong>Quick Navigation Submenu</strong> field nests it under a named submenu instead of the root — use <code>/</code> to nest multiple levels deep (e.g. <code>Tools/Network</code> for a two-level submenu); leave it empty to keep the command at the top level. A command shown this way runs with its configured parameters as-is, since there&#39;s no typed argument text to substitute into <code>%s1</code>/<code>%s</code> here.</p><hr><p>None of the plugins on this page are required — each can be disabled independently under <a href="./settings/plugins.html">Settings → Plugins</a> if you don&#39;t want it competing for keyboard space, and <a href="./search-syntax.html">Search Syntax</a> covers the separate, always-active fuzzy query language used for everything else (files, folders, applications).</p>`,37)])])}const g=t(s,[["render",r]]);export{p as __pageData,g as default};
